package org.gameflex.tv;
import android.app.*;import android.os.*;import android.view.*;import android.webkit.*;import android.view.inputmethod.InputMethodManager;import android.content.Context;import android.net.Uri;import android.graphics.Color;import org.json.*;import java.net.*;import java.io.*;
public final class StartupDialog extends Dialog {
 public interface Listener{void server(String url,boolean remember);void local(boolean remember);void cancelled();}
 private final Activity activity;private final Listener listener;private WebView view;private boolean editing=false,selected=false,closed=false;
 public StartupDialog(Activity a,String server,String mode,Listener l){super(a);activity=a;listener=l;view=new WebView(a);WebSettings s=view.getSettings();s.setJavaScriptEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setBlockNetworkLoads(false);view.setBackgroundColor(Color.TRANSPARENT);view.setFocusable(true);view.setFocusableInTouchMode(true);
  view.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return LocalAssets.response(a.getAssets(),r.getUrl().toString());}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!r.isForMainFrame()||!LocalAssets.trusted(v.getUrl()))return true;if(!"gameflex-setup".equals(u.getScheme()))return true;boolean remember="1".equals(u.getQueryParameter("remember"));if("cancel".equals(u.getHost())){cancel();return true;}if("local".equals(u.getHost())){selected=true;dismiss();listener.local(remember);return true;}if("connect".equals(u.getHost()))probe(u.getQueryParameter("url"),remember);return true;}@Override public void onPageFinished(WebView v,String url){try{JSONObject data=new JSONObject().put("server",server).put("mode",mode);v.evaluateJavascript("GameFlexSetup.configure("+data+")",null);}catch(Exception ignored){}}});
  setContentView(view);setOnCancelListener(d->l.cancelled());setOnDismissListener(d->{closed=true;view.destroy();});setOnKeyListener((d,key,e)->{if(editing){if(key==4&&e.getAction()==1){editing=false;((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(view.getWindowToken(),0);return true;}return false;}String dir=key==19?"up":key==20?"down":key==21?"left":key==22?"right":null;if(dir!=null){if(e.getAction()==0)view.evaluateJavascript("GameFlexSetup.move('"+dir+"')",null);return true;}if(key==23||key==66){if(e.getAction()==1)view.evaluateJavascript("GameFlexSetup.activate()",r->{if("\"input\"".equals(r)){editing=true;view.requestFocus();((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(view,InputMethodManager.SHOW_IMPLICIT);}});return true;}return false;});
  view.loadUrl(LocalAssets.ORIGIN+"/local/startup.html");
 }
 @Override public void show(){super.show();getWindow().setBackgroundDrawableResource(android.R.color.transparent);getWindow().setLayout(-1,-1);view.requestFocus();}
 private void error(String message){if(!closed)view.evaluateJavascript("GameFlexSetup.error("+JSONObject.quote(message)+")",null);}
 private void probe(String text,boolean remember){final String url;try{url=ServerPolicy.parse(text==null?"":text).toString();}catch(Exception e){error("Adresse refusée. Utilisez l’adresse IP locale de votre serveur GameFlex et son port.");return;}new Thread(()->{HttpURLConnection c=null;boolean ok=false;try{c=(HttpURLConnection)new URL(url+"/api/v1/consoles").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setInstanceFollowRedirects(false);int status=c.getResponseCode();if(status==401||status==403)ok=true;else if(status==200){ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] data=new byte[4096];int n;while((n=in.read(data))!=-1){if(b.size()+n>512*1024)throw new IOException();b.write(data,0,n);}}Object response=new JSONTokener(b.toString("UTF-8")).nextValue();ok=response instanceof JSONArray||response instanceof JSONObject&&((JSONObject)response).has("data");}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}final boolean result=ok;activity.runOnUiThread(()->{if(closed)return;if(result){selected=true;dismiss();listener.server(url,remember);}else error("Serveur injoignable. Vérifiez son adresse et le Wi-Fi, ou choisissez Sur cette TV.");});},"GameFlex-server-check").start();}
}
